// ChatComponent.tsx
import React, { useEffect, useState } from 'react';
import io from 'socket.io-client';

const socket = io('http://localhost:5000');

const ChatComponent = ({ jobSeekerId, agencyId }) => {
   const [messages, setMessages] = useState([]);
   const [message, setMessage] = useState('');

   useEffect(() => {
      socket.emit('join_room', `${jobSeekerId}_${agencyId}`);
      socket.on('receive_message', (data) => {
         setMessages((prevMessages) => [...prevMessages, data]);
      });

      return () => {
         socket.disconnect();
      };
   }, [jobSeekerId, agencyId]);

   const sendMessage = () => {
      const newMessage = { sender_id: jobSeekerId, receiver_id: agencyId, message_content: message };
      socket.emit('send_message', { ...newMessage, room: `${jobSeekerId}_${agencyId}` });
      setMessages((prevMessages) => [...prevMessages, newMessage]);
      setMessage('');
   };

   return (
      <div>
         <div>
            {messages.map((msg, index) => (
               <div key={index}>
                  <strong>{msg.sender_id === jobSeekerId ? 'You' : 'Agency'}:</strong> {msg.message_content}
               </div>
            ))}
         </div>
         <input
            type="text"
            value={message}
            onChange={(e) => setMessage(e.target.value)}
            placeholder="Type a message"
         />
         <button onClick={sendMessage}>Send</button>
      </div>
   );
};

export default ChatComponent;
